package com.cpf.starter.ibmmq;import com.cpf.core.api.broker.*;import java.time.Instant;import org.springframework.jms.JmsException;import org.springframework.jms.core.JmsTemplate;public final class CpfIbmMqBrokerClient implements CpfBrokerClient {private final JmsTemplate template;private final CpfIbmMqProperties p;public CpfIbmMqBrokerClient(JmsTemplate t,CpfIbmMqProperties p){template=t;this.p=p;}public CpfBrokerPublishResult enqueue(CpfBrokerPublishRequest r){if(r.payload().length>p.getMaxPayloadBytes())throw new IllegalArgumentException("IBM MQ payload limit");try{template.send(p.getDestination(),s->{var m=s.createBytesMessage();m.writeBytes(r.payload());m.setJMSCorrelationID(r.transactionId());m.setStringProperty("cpfMessageId",r.messageId());m.setStringProperty("cpfIdempotencyKey",r.idempotencyKey());return m;});return new CpfBrokerPublishResult("PUBLISHED",r.messageId(),"IBM_MQ",p.getDestination(),Instant.now(),"JMS transaction accepted");}catch(JmsException ex){throw new UnknownResultException(reason(ex),ex);}}private static String reason(Throwable t){for(Throwable x=t;x!=null;x=x.getCause()){String m=x.getMessage();if(m!=null&&m.matches(".*\\b(2[0-9]{3})\\b.*"))return m.replaceAll(".*\\b(2[0-9]{3})\\b.*","$1");}return "UNMAPPED";}public static final class UnknownResultException extends RuntimeException{public UnknownResultException(String reason,Throwable c){super("IBM MQ in-doubt reason="+reason+"; reconcile before retry",c);}}}
